import { Entity } from "ecs";
import { World } from "../ecs";

export type Pattern = {
  name:
    | "passive"
    | "chase"
    | "chase_slow"
    | "prism"
    | "eye"
    | "orb"
    | "fairy"
    | "archer"
    | "rose"
    | "violet"
    | "clover"
    | "tulip"
    | "ilex"
    | "tutorial_boss"
    | "oak_boss"
    | "oak_tower"
    | "oak_lily"
    | "golem"
    | "worm_boss"
    | "worm_tower"
    | "chest_boss"
    | "wave_tower"
    | "wait"
    | "action"
    | "invincible"
    | "vulnerable"
    | "move"
    | "kill"
    | "heal"
    | "dialog"
    | "shout"
    | "lock"
    | "unlock"
    | "collect"
    | "drop"
    | "sell"
    | "enrage"
    | "soothe"
    | "tumbleweed"
    | "worm"
    | "fish"
    | "chick"
    | "spawner"
    | "habitat"
    | "dummy"
    | "guard"
    | "gate"
    | "watch";
  memory: any;
};

export type Behaviour = {
  patterns: Pattern[];
};

export const BEHAVIOUR = "BEHAVIOUR";

export default function addBehaviour(
  world: World,
  entity: Entity,
  behaviour: Behaviour
) {
  world.addComponentToEntity(entity, BEHAVIOUR, behaviour);
}
