const menuDelay = 5000;

export const menuQuest: Sequence<QuestSequence> = (world, entity, state) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };
  const menuSign = getIdentifierAndComponents(world, "menu_sign", [POSITION]);
  const menuPortal = world.getEntities([WARPABLE])[0];

  // remember initial hero position
  if (!state.args.memory.initialPosition) {
    state.args.memory.initialPosition = copy(entity[POSITION]);
  }

  const hasMoved =
    entity[POSITION].x !== state.args.memory.initialPosition.x ||
    entity[POSITION].y !== state.args.memory.initialPosition.y;

  step({
    stage,
    name: START_STEP,
    isCompleted: () => true,
    onLeave: () => "wait",
  });

  step({
    stage,
    name: "wait",
    isCompleted: () => hasMoved || stage.state.elapsed > menuDelay,
    onLeave: () => (hasMoved ? "sign" : "move"),
  });

  step({
    stage,
    name: "move",
    onEnter: () => {
      entity[TOOLTIP].override = "visible";
      entity[TOOLTIP].dialogs = [
        createDialog(
          isTouch ? "Swipe to move" : "\u011a \u0117 \u0118 \u0119 to move"
        ),
      ];
      entity[TOOLTIP].changed = true;
      return true;
    },
    isCompleted: () => hasMoved,
    onLeave: () => {
      entity[TOOLTIP].override = undefined;
      entity[TOOLTIP].dialogs = [];
      entity[TOOLTIP].changed = true;
      return "sign";
    },
  });

  step({
    stage,
    name: "sign",
    onEnter: () => {
      setHighlight(world, "quest", menuSign);
      return true;
    },
    isCompleted: () =>
      !!menuSign &&
      !isInPopup(world, entity) &&
      !getSequence(world, menuSign, "discovery"),
    onLeave: () => "warp",
  });

  step({
    stage,
    name: "warp",
    onEnter: () => {
      setHighlight(world, "quest", menuPortal);
      return true;
    },
    isCompleted: () => true,
    onLeave: () => END_STEP,
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const centerQuest: Sequence<QuestSequence> = (world, entity, state) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const centerUpDoor = assertIdentifierAndComponents(world, "center:door", [
    POSITION,
  ]);
  const spawnSign = getIdentifierAndComponents(world, "spawn_sign", [POSITION]);
  const spawnKey = getIdentifierAndComponents(world, "spawn_key", [POSITION]);

  // save hero position to update highlight
  if (!state.args.memory.savedPosition) {
    state.args.memory.savedPosition = copy(entity[POSITION]);
  }

  const hasMoved =
    entity[POSITION].x !== state.args.memory.savedPosition.x ||
    entity[POSITION].y !== state.args.memory.savedPosition.y;
  const inEntrance =
    getLockable(world, entity[POSITION])?.[LOCKABLE].type === "entry";

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !inEntrance,
    onLeave: () => "move",
  });

  step({
    stage,
    name: "end",
    forceEnter: () =>
      isUnlocked(world, centerUpDoor) ||
      (state.args.step !== START_STEP && inEntrance) ||
      (!spawnSign && state.args.step === "sign"),
    onEnter: () => {
      setHighlight(world);
      return true;
    },
    isCompleted: () => true,
    onLeave: () => END_STEP,
  });

  step({
    stage,
    name: "move",
    isCompleted: () => hasMoved,
    onLeave: () => "sign",
  });

  step({
    stage,
    name: "sign",
    onEnter: () => {
      setHighlight(world, "quest", spawnSign);
      return true;
    },
    isCompleted: () =>
      !!spawnSign &&
      !isInPopup(world, entity) &&
      !getSequence(world, spawnSign, "discovery"),
    onLeave: () => "key",
  });

  step({
    stage,
    name: "key",
    onEnter: () => {
      setHighlight(world, "quest", spawnKey);
      return true;
    },
    isCompleted: () => !spawnKey,
    onLeave: () => "door",
  });

  step({
    stage,
    name: "door",
    onEnter: () => {
      setHighlight(world, "quest", centerUpDoor);
      return true;
    },
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const north1Quest: Sequence<QuestSequence> = (world, entity, state) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const entityId = world.getEntityId(entity);

  const north1UpDoor = assertIdentifierAndComponents(world, "north1:door", [
    POSITION,
  ]);
  const guideEntity = getIdentifierAndComponents(world, "guide", [POSITION]);
  const guideSign = getIdentifierAndComponents(world, "guide_sign", [POSITION]);
  const woodOne = getIdentifierAndComponents(world, "wood_one", [POSITION]);
  const dummy = getIdentifierAndComponents(world, "dummy", [POSITION]);
  const coinDrop = getIdentifiersAndComponents(world, "dummy:drop", [
    ITEM,
  ]).find((drop) => drop[ITEM].stackable === "coin");
  const inEntrance =
    getLockable(world, entity[POSITION])?.[LOCKABLE].type === "entry";

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !inEntrance,
    onLeave: () => "sign",
  });

  step({
    stage,
    name: "end",
    forceEnter: () =>
      isUnlocked(world, north1UpDoor) ||
      (state.args.step !== START_STEP && inEntrance) ||
      (!guideSign && state.args.step === "sign"),
    onEnter: () => {
      setHighlight(world);
      return true;
    },
    isCompleted: () => true,
    onLeave: () => END_STEP,
  });

  step({
    stage,
    name: "sign",
    onEnter: () => {
      setHighlight(world, "quest", guideSign);
      return true;
    },
    isCompleted: () =>
      !!guideSign &&
      !isInPopup(world, entity) &&
      !getSequence(world, guideSign, "discovery"),
    onLeave: () => "stick",
  });

  step({
    stage,
    name: "stick",
    onEnter: () => {
      setHighlight(world, "quest", woodOne);
      return true;
    },
    isCompleted: () => !!entity[EQUIPPABLE].weapon,
    onLeave: () => "dummy",
  });

  step({
    stage,
    name: "dummy",
    onEnter: () => {
      setHighlight(world, "enemy", dummy);
      return true;
    },
    isCompleted: () => !dummy && !!coinDrop,
    onLeave: () => "coin",
  });

  step({
    stage,
    name: "coin",
    onEnter: () => {
      const carrierEntity = world.getEntityByIdAndComponents(
        coinDrop?.[ITEM].carrier,
        [POSITION]
      );
      setHighlight(world, "quest", carrierEntity);
      return true;
    },
    isCompleted: () => coinDrop?.[ITEM].carrier === entityId,
    onLeave: () => "shop",
  });

  step({
    stage,
    name: "shop",
    onEnter: () => {
      setHighlight(world, "quest", guideEntity);
      return true;
    },
    isCompleted: () =>
      !!(entity[INVENTORY] as Inventory).items.find((item) => {
        const itemEntity = world.assertByIdAndComponents(item, [ITEM]);
        return (
          itemEntity[ITEM].consume === "key" &&
          itemEntity[ITEM].material === "iron"
        );
      }) && !isInPopup(world, entity),
    onLeave: () => "door",
  });

  step({
    stage,
    name: "door",
    onEnter: () => {
      setHighlight(world, "quest", north1UpDoor);
      return true;
    },
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const north2Quest: Sequence<QuestSequence> = (world, entity, state) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const north2UpDoor = assertIdentifierAndComponents(world, "north2:door", [
    POSITION,
  ]);
  const north2RightDoor = assertIdentifierAndComponents(
    world,
    "north2east1:door",
    [POSITION]
  );
  const fruitSign = getIdentifierAndComponents(world, "fruit_sign", [POSITION]);
  const fruitChest = getIdentifierAndComponents(world, "fruit_chest", [
    POSITION,
  ]);
  const inEntrance =
    getLockable(world, entity[POSITION])?.[LOCKABLE].type === "entry";

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !inEntrance,
    onLeave: () => "cactus",
  });

  step({
    stage,
    name: "end",
    forceEnter: () =>
      (isUnlocked(world, north2UpDoor) && isUnlocked(world, north2RightDoor)) ||
      (state.args.step !== START_STEP && inEntrance) ||
      (!fruitSign && state.args.step === "sign"),
    onEnter: () => {
      setHighlight(world);
      return true;
    },
    isCompleted: () => true,
    onLeave: () => END_STEP,
  });

  const cactusEntities = [-1, 0, 1]
    .map((cactusOffset) =>
      Object.values(
        getCell(world, add(up2Cactus, { x: cactusOffset, y: 0 }))
      ).find((entity) => isSpikable(world, entity))
    )
    .filter(Boolean);
  step({
    stage,
    name: "cactus",
    onEnter: () => {
      setHighlight(world, "enemy", cactusEntities[1]);
      return true;
    },
    isCompleted: () => cactusEntities.length < 3,
    onLeave: () => "sign",
  });

  step({
    stage,
    name: "sign",
    onEnter: () => {
      setHighlight(world, "quest", fruitSign);
      return true;
    },
    isCompleted: () =>
      !!fruitSign &&
      !isInPopup(world, entity) &&
      !getSequence(world, fruitSign, "discovery"),
    onLeave: () => "chest",
  });

  step({
    stage,
    name: "chest",
    onEnter: () => {
      setHighlight(world, "enemy", fruitChest);
      return true;
    },
    isCompleted: () => !fruitChest,
    onLeave: () => "gold_door",
  });

  step({
    stage,
    name: "gold_door",
    onEnter: () => {
      setHighlight(world, "quest", north2RightDoor);
      return true;
    },
    isCompleted: () =>
      !!(entity[INVENTORY] as Inventory).items.find((item) => {
        const itemEntity = world.assertByIdAndComponents(item, [ITEM]);
        return (
          itemEntity[ITEM].consume === "key" &&
          itemEntity[ITEM].material === "iron"
        );
      }),
    onLeave: () => "iron_door",
  });

  step({
    stage,
    name: "iron_door",
    onEnter: () => {
      setHighlight(world, "quest", north2UpDoor);
      return true;
    },
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const north2East1Quest: Sequence<QuestSequence> = (
  world,
  entity,
  state
) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const north2UpDoor = assertIdentifierAndComponents(world, "north2:door", [
    POSITION,
  ]);
  const north2RightDoor = assertIdentifierAndComponents(
    world,
    "north2east1:door",
    [POSITION]
  );
  const potionChest = getIdentifierAndComponents(world, "potion_chest", [
    POSITION,
  ]);
  const inEntrance =
    getLockable(world, entity[POSITION])?.[LOCKABLE].type === "entry";

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !inEntrance,
    onLeave: () => "chest",
  });

  step({
    stage,
    name: "end",
    forceEnter: () =>
      (state.args.step !== START_STEP && inEntrance) || !potionChest,
    onEnter: () => {
      if (isUnlocked(world, north2UpDoor)) {
        setHighlight(world);
      } else {
        setHighlight(world, "quest", north2RightDoor);
      }
      return true;
    },
    isCompleted: () => true,
    onLeave: () => END_STEP,
  });

  step({
    stage,
    name: "chest",
    onEnter: () => {
      setHighlight(world, "enemy", potionChest);
      return true;
    },
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const spawnQuest: Sequence<QuestSequence> = (world, entity, state) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };
  const size = world.metadata.gameEntity[LEVEL].size;
  const spawnSign = getIdentifierAndComponents(world, "spawn_sign", [POSITION]);
  const earthChief = getIdentifierAndComponents(world, "earthChief", [
    POSITION,
  ]);

  const townDistance = earthChief
    ? getDistance(entity[POSITION], earthChief[POSITION], size)
    : Infinity;

  step({
    stage,
    name: START_STEP,
    onEnter: () => {
      setHighlight(world, "quest", spawnSign);
      return true;
    },
    isCompleted: () =>
      townDistance < 10 ||
      !spawnSign ||
      !getSequence(world, spawnSign, "discovery") ||
      (isInPopup(world, entity) &&
        world.getEntityById(entity[PLAYER].popup) === spawnSign),
    onLeave: () => "town",
  });

  step({
    stage,
    name: "town",
    onEnter: () => {
      setHighlight(world, "quest", earthChief, earthChief && { x: 0, y: 0 });
      return true;
    },
    isCompleted: () =>
      !earthChief ||
      (isInPopup(world, entity) &&
        entity[PLAYER].popup === world.getEntityId(earthChief)),
    onLeave: () => {
      setHighlight(world);
      return END_STEP;
    },
  });

  return { updated: stage.updated, finished: stage.finished };
};

export const waypointQuest: Sequence<QuestSequence> = (
  world,
  entity,
  state
) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };
  const { identifier, targetId, position, distance, highlight, quadrant } =
    state.args.memory;

  const size = world.metadata.gameEntity[LEVEL].size;
  const targetEntity = position
    ? position
    : identifier
    ? getIdentifierAndComponents(world, identifier, [POSITION])
    : world.getEntityByIdAndComponents(targetId || state.args.giver, [
        POSITION,
      ]);

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !!targetEntity,
    onLeave: () => "search",
  });

  step({
    stage,
    name: "search",
    onEnter: () => {
      setHighlight(world, highlight || "quest", targetEntity, quadrant);
      return true;
    },
    isCompleted: () =>
      !!targetEntity &&
      getDistance(entity[POSITION], targetEntity[POSITION], size) <= distance,
    onLeave: () => {
      setHighlight(world);
      return END_STEP;
    },
  });

  return { updated: stage.updated, finished: stage.finished };
};

const tombstoneDistance = 1.3;

export const tombstoneQuest: Sequence<QuestSequence> = (
  world,
  entity,
  state
) => {
  const stage: QuestStage<QuestSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };
  const size = world.metadata.gameEntity[LEVEL].size;
  const tombstoneEntity = world.getEntityByIdAndComponents(state.args.giver, [
    POSITION,
  ]);

  step({
    stage,
    name: START_STEP,
    isCompleted: () => !!tombstoneQuest,
    onLeave: () => "search",
  });

  step({
    stage,
    name: "search",
    onEnter: () => {
      setHighlight(world, "tombstone", tombstoneEntity);
      return true;
    },
    isCompleted: () =>
      !!tombstoneEntity &&
      getDistance(entity[POSITION], tombstoneEntity[POSITION], size) <=
        tombstoneDistance,
    onLeave: () => {
      setHighlight(world);

      // restart existing quest
      const currentQuest = (entity[SPAWNABLE] as Spawnable).quest;

      if (currentQuest) {
        disposeSequence(world, entity, "quest");
        questSequence(
          world,
          entity,
          currentQuest.name as any,
          currentQuest.args.memory,
          world.getEntityById(currentQuest.args.giver)
        );
        entity[SPAWNABLE].quest = undefined;
      }

      // don't finish quest to avoid deletion of newly started quest
      return "wait";
    },
  });

  return { updated: stage.updated, finished: stage.finished };
};
